<?php
session_start(); // Start the session at the very beginning

// --- Define Admin Credentials ---
// !!! SECURITY WARNING !!!
// Storing plain text passwords or even hashes directly in code is NOT ideal for production.
// Consider environment variables or a configuration file outside the web root later.
// For now, we'll use a hash generated by password_hash().
// You can generate a hash for your chosen password using a separate script or online tool.
// Example: To generate a hash for "adminpassword123":
// echo password_hash("adminpassword123", PASSWORD_DEFAULT);
// Replace the example hash below with the one you generate.

define('ADMIN_USERNAME', 'admin'); // Set your desired admin username
define('ADMIN_PASSWORD_HASH', '$2y$10$bo0pVTaeJvW9/wxthn.8IOTLJrhpnGk5kCNjge4Hh3Pe19uRZmun.'); // <-- REPLACE THIS HASH

$error_message = ''; // Initialize error message variable

// --- Process Login Form Submission ---
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = $_POST['username'] ?? '';
    $password = $_POST['password'] ?? '';

    // Verify credentials
    if ($username === ADMIN_USERNAME && password_verify($password, ADMIN_PASSWORD_HASH)) {
        // Password is correct!

        // Regenerate session ID for security (prevents session fixation)
        session_regenerate_id(true);

        // Set session variable to mark user as logged in
        $_SESSION['is_admin'] = true;

        // Redirect to the admin moderation page
        header('Location: admin_moderate.php');
        exit();

    } else {
        // Invalid credentials
        $error_message = "Invalid username or password.";
    }
}

// --- Redirect if already logged in ---
// If the user is already logged in and tries to access login page, redirect them
if (isset($_SESSION['is_admin']) && $_SESSION['is_admin'] === true) {
    header('Location: admin_moderate.php');
    exit();
}

?>
